// The original's code of Scripts/32_Маркеры сносок/12_Создать таблицу соответствия маркеров будущих сносок.js
// (FictionBook Editor 2.7.9, by stokber), kept as written - generated by the conversion from the
// 2.7.9 file - with these rewrites only, so that it runs in the editor's sandbox:
//  1. Run() is the module's async function engine(host, tx, js); the variables it used without
//     declaring them (i) are declared, a module being strict code;
//  2. fbw_body.innerHTML is host.innerHTML, the page rebuilt from the book (lib/marker-page.js);
//  3. the dialog "HTML/Создать таблицу маркеров-сносок.htm" (with the IE 6 check of its size) is
//     host.chooseMarker(), a form, and the kind of markers in the messages is host.label(markSign);
//  4. MsgBox, alert and window.clipboardData.setData are the host's and awaited, so Report is
//     async and awaited too;
//  5. the setting display stays: 0 shows the table in a report window (MyMsgWindow, which wrote it
//     into the window of "HTML/Создать таблицу маркеров-сносок.htm"), 1 - the original's default -
//     writes it into a file and shows it (WriteFile, which wrote filePatch, "HTML/temp.html" next
//     to the program, with FileSystemObject and opened it in the default browser): the editor's
//     Save dialog proposes "temp.html", the user chooses where, and the report window shows it;
//  6. every regular expression is compiled with JScript's meaning (js(): \s without the Unicode
//     spaces, . matching \r as well);
//  7. every text is tx(ru, en): the Russian in the Russian interface, the English otherwise; the
//     values of the dialog's choice compared with markSign stay as they are.
// The comments, the names and the order of the statements are the original's.

export async function engine(host, tx, js) {
var i; // used undeclared by the original

                   ///НАСТРОЙКИ
    var display = 1; // 0 - показывать в IE, 1 - в браузере по умолчанию.
    // путь для показа в браузере по умолчанию:
    if (display == 1) {
       // путь для временного html-файла создаваемого для вашего браузера по умолчанию (HTML/temp.html):
       var filePatch = "temp.html";
       // или указать любой другой путь, например:
       // var filePatch = "C:\\temp.html"; // Следует иметь ввиду, что скрипт не создаёт новых директорий. Все папки, как и диски указанные в этой переменной, должны реально существовать.
    }
    // ================================

    var name = tx("Создать таблицу соответствия маркеров будущих сносок", "Create a table matching the markers of future footnotes");
    var version = "1.2";
    var avtor = "stokber";
    var str = host.innerHTML;
    var s1 = "☺"; //метка начала маркера сноски.
    var s2 = "☻"; //метка конца маркера сноски.
    var nZ;
    var nT;
    var report = "";
    var colour0a = "DarkKhaki"; // цвет фона Заголовков таблицы.;
    var colour0d = "#c0c0c0"; // цвет пустых ячеек.
    var colour0e = "DarkKhaki"; // цвет среднего столбца с номерами будущих сносок.
    var colorErr = "red"; // цвет шрифта первого ошибочного номера будущей сноски.
    var colour1 = "Khaki"; // цвет первой полосы «зебры».
    var colour2 = "orange"; // цвет второй полосы «зебры».


    var lenZ = 120; // кол. символов для отображения в ячейке для маркера знака сноски.
    var lenT = 120; // кол. символов для отображения в ячейке для маркера текста сноски.

    // окно выбора вида маркеров сносок:
    var markSign = await host.chooseMarker();
    if (!markSign) return;

    // Проверяем случайное наличие в документе символов ☺ и ☻, которые
    // будут использоваться скриптом как временные метки s1 и  s2 маркеров сносок
    // в  переменной str:
    var regexp = js(new RegExp("(" + s1 + "|" + s2 + ")+", "g"))
    /*    var metk = (str.match(regexp) || []).length;
      // var Metk = (str.match(/☺|☻/g) || []).length;
    if (metk > 0) { */
    if (regexp.test(str)) {
        await host.clipboard("(" + s1 + "|" + s2 + ")+");
        await host.alert(tx("В вашем документе имеются символ(ы) ", "Your document has the character(s) ") + s1 + tx(" и(ли) ", " and/or ") + s2 + tx(", которые используются скриптом как временные метки. Для корректной работы рекомендуем на время работы скрипта заменить их на другие символы.\nНайти в документе их можно перейдя в режим Кода и вставив регулярное выражение из буфера обмена в строку поиска окна Поиск (Ctrl+F)\n\"", ", which the script uses as temporary marks. For it to work correctly, replace them by other characters while you use the script.\nYou can find them in the document by switching to the Source view and pasting the regular expression from the clipboard into the search field of the Find window (Ctrl+F)\n\"") + name + "\" v." + version);
        return;
    }

    if (markSign == "надстрочным текстом") {
        str = str.replace(js(/<\/?(STRONG|EM|SUB|STRIKE)>/ig), "");
        str = str.replace(js(/<SPAN class=code>(.+?)<\/SPAN>/ig), "$1"); //
        str = str.replace(js(/<A class=note [^<]+?><SUP>(\d+)<\/SUP><\/A>/ig), "$1"); // убить FineReader-ские сноски.
        // str = str.replace(/(<A href=[^>]+>)<SUP>(\{\d+\})<\/SUP>(<\/A>)/ig, "$1$2$3");

        str = str.replace(js(/&nbsp;/g), " "); //
        str = str.replace(js(/[ □▫◦]/g), " "); //
        str = str.replace(js(/<SUP>\s*(\d+)(\s*)<\/SUP>/ig), s1 + "$1" + s2 + "$2"); //подменяем теги SUP на метки.
        str = str.replace(js(/<\/?[^<>]+>/g), ""); // удаляем все теги.
        str = str.replace(js(/[¹²³⁴⁵⁶⁷⁸⁹⁰]+/g), s1 + "$&" + s2); // учитываем надстрочные символы цифр.

    } else if (markSign == "вида *") {
        str = str.replace(js(/<\/?(STRONG|EM|SUP|SUB|STRIKE)>/ig), "");
        str = str.replace(js(/<SPAN class=code>(.+?)<\/SPAN>/ig), "$1"); //
        str = str.replace(js(/&nbsp;(&nbsp;| |\*)/g), " $1"); //
        str = str.replace(js(/(&nbsp;| |\*)&nbsp;/g), "$1 "); //
        str = str.replace(js(/[ □▫◦]/g), " "); //
        for (; countAst != 0;) { // заменяем звездочки в пустых строках другими символами (@).
            var ast = js(new RegExp("^((?:<\\/?[^>]+>)*)([ @]*)([*])([ *]*)((?:<\\/?[^>]+>)*)$", "gm"));
            var ast_ = "$1$2@$4$5";
            var countAst = 0;
            if (str.search(ast) != -1) {
                str = str.replace(ast, ast_);
                countAst++
            }
        }
        str = str.replace(js(/[*]+/ig), s1 + "$&" + s2);

    } else if (markSign == "вида #") {
        str = str.replace(js(/<\/?(STRONG|EM|SUP|SUB|STRIKE)>/ig), "");
        str = str.replace(js(/<SPAN class=code>(.+?)<\/SPAN>/ig), "$1"); //
        str = str.replace(js(/&nbsp;(&nbsp;| |#)/g), " $1"); //
        str = str.replace(js(/(&nbsp;| |#)&nbsp;/g), "$1 "); //
        str = str.replace(js(/[ □▫◦]/g), " "); //
        for (; countGrid != 0;) { // заменяем решётки в пустых строках другими символами (@).
            var grid = js(new RegExp("^((?:<\\/?[^>]+>)*)([ @]*)([#])([ #]*)((?:<\\/?[^>]+>)*)$", "gm"));
            var grid_ = "$1$2@$4$5";
            var countGrid = 0;
            if (str.search(grid) != -1) {
                str = str.replace(grid, grid_);
                countGrid++
            }
        }
        str = str.replace(js(/[#]+/ig), s1 + "$&" + s2);

    } else if (markSign == "вида [1]") {
        str = str.replace(js(/<\/?(STRONG|EM|SUP|SUB|STRIKE)>/ig), "");
        str = str.replace(js(/<SPAN class=code>(.+?)<\/SPAN>/ig), "$1"); //
        str = str.replace(js(/(<A class=note [^<]+?>)\[(\d+)\](<\/A>)/ig), "$1($2)$3"); //
        str = str.replace(js(/\[\d+\]/ig), s1 + "$&" + s2);
        str = str.replace(js(/(<A class=note [^<]+?>)\((\d+)\)(<\/A>)/ig), "$1[$2]$3"); //
    } else if (markSign == "вида {1}") {
        str = str.replace(js(/<\/?(STRONG|EM|SUP|SUB|STRIKE)>/ig), "");
        str = str.replace(js(/<SPAN class=code>(.+?)<\/SPAN>/ig), "$1"); //
        str = str.replace(js(/(<A href=[^<]+?>)\{(\d+)\}(<\/A>)/ig), "$1($2)$3"); //
        str = str.replace(js(/\{\d+\}/ig), s1 + "$&" + s2);
        str = str.replace(js(/(<A href=[^<]+?>)\((\d+)\)(<\/A>)/ig), "$1{$2}$3"); //
    } else if (markSign == "вида [~1~]") {
        str = str.replace(js(/\[~\d+~\]/ig), s1 + "$&" + s2);
    }

    if (markSign == "вида {~1~}") {
        str = str.replace(js(/\{~\d+~\}/ig), s1 + "$&" + s2);
    }

    await Report();

    async function Report() {
        str = str.replace(js(/<\/?[^<>]+>/g), ""); // удаляем все теги
        str = str.replace(js(/&lt;/g), "<"); //
        str = str.replace(js(/&gt;/g), ">"); //
        str = str.replace(js(/&amp;/g), "&"); //
        str = str.replace(js(/&nbsp;/g), " "); //
        str = str.replace(js(/[ □▫◦]/g), " ");
        str = str.replace(js(/^\s+/gm), ""); // удаляем начальные пробелы

        var regexp = js(new RegExp(s1, "g"));
        var colMarker = (str.match(regexp) || []).length;
        if (colMarker == 0) {
            await host.msgBox(tx("Не найдено ни одного маркера сносок ", "No footnote markers were found: ") + host.label(markSign) + tx(".\nТаблица создана не будет.\n\nСкрипт \"", ".\nNo table will be created.\n\nScript \"") + name + "\" v." + version);
            return;
        }
        var regexp = js(new RegExp("^" + s1, "gm"))
        // var t = (str.match(/^☺/gm) || []).length;
        var t = (str.match(regexp) || []).length;
        var z = (colMarker - t);
        if (t == 0 || z == 0) {
            await host.msgBox(tx("Вы выбрали маркеры ", "You chose the markers ") + host.label(markSign) + tx(".\n\nНайдено:\nмаркеров знаков сносок: ", ".\n\nFound:\nfootnote reference markers: ") + z + tx(" \nмаркеров текстов сносок : ", " \nfootnote text markers : ") + t + tx("\nТаблица создана не будет.\n\n\Скрипт \"", "\nNo table will be created.\n\nScript \"") + name + "\" v." + version);
            return;
        }

        var regexpZ = js(new RegExp("([^" + s2 + "\\n\\r]{1," + lenZ + "})(" + s1 + ".+?" + s2 + ")", "gm")); // регулярное выражение для маркера номера сноски.
        var regexpT = js(new RegExp("^(" + s1 + ".+?" + s2 + ")([^" + s1 + "\\n\\r]{1," + lenT + "})", "gm")); // регулярное выражение для маркера текста сноски.

        var resultZ;
        var reportZ = ""; // список маркеров знаков сносок.
        var resultT;
        var reportT = ""; // список маркеров текстов сносок.

        while (resultZ = regexpZ.exec(str)) {
            reportZ += (resultZ[0]) + "\r\n"; // для маркера номера сноски.
        }

        while (resultT = regexpT.exec(str)) {
            reportT += (resultT[0]) + "\r\n"; // для маркера номера текста сноски.
        }

        var j;
        nZ = str.match(regexpZ).length; // список маркеров знаков сносок.
        nT = str.match(regexpT).length; // список маркеров текстов сносок.
        if (nZ >= nT) j = nZ;
        else
            j = nT;

        var start;
        var fin;
        var razn;

        for (i = 0; i < j; i++) {
            var sZ = reportZ.split("\r\n");
            var sT = reportT.split("\r\n");
            var num = ([i]);
            num++
            report += (sZ[i] + "\t" + num + "\t" + sT[i]) + "\r\n";

        }

        // добавляем вр. метку в виде трех нолей в те строки где числовые значения маркеров знаков и текстов сносок не равны:
        report = report.replace(js(new RegExp("(" + s1 + ".+" + s2 + ")(\\t)(\\d+)(\\t)(?!\\1)", "g")), "$1$2000$3$4");


        report = report.replace(js(/^(undefined)?\t/mg), "\t");
        report = report.replace(js(/\t(undefined)?$/mg), "\t");

        if (markSign == "надстрочным текстом") {
            report = report.replace(js(/☺/mg), "<sup>");
            report = report.replace(js(/☻/mg), "</sup>");
        }

        report = report.replace(js(/[☺☻]/mg), "");
        report = report.replace(js(/^([^\t\r\n]*)\t(\d+)\t([^\t\r\n]*)$/gm), "<tr><td align=\"right\">$1</td><td align=\"center\">$2</td><td>$3</td></tr>");

        report = report.replace(js(/(<tr>.+?\n)<tr>/gm), "$1<tr BGCOLOR=\"" + colour1 + "\">");
        report = report.replace(js(/<tr>/gm), "<tr BGCOLOR=\"" + colour1 + "\">");

        // задаём фон для фрагментов с маркерами №1:
        if (markSign == "надстрочным текстом") {
            report = report.replace(js(/(<td align=\"right\")>(.*?<sup>1<\/sup><\/td>)/gm), "$1 BGCOLOR=\"" + colour2 + "\">$2");
            report = report.replace(js(/(<td)>(<sup>1<\/sup>.+?<\/td><\/tr>)/gm), "$1 BGCOLOR=\"" + colour2 + "\">$2");
        }
        if (markSign == "вида *") {
            report = report.replace(js(/(<td align=\"right\")>(.*?[^*]\*<\/td>)/gm), "$1 BGCOLOR=\"" + colour2 + "\">$2");
            report = report.replace(js(/(<td)>(\*[^*].+?<\/td><\/tr>)/gm), "$1 BGCOLOR=\"" + colour2 + "\">$2");
        }
		if (markSign == "вида #") {
            report = report.replace(js(/(<td align=\"right\")>(.*?[^#]#<\/td>)/gm), "$1 BGCOLOR=\"" + colour2 + "\">$2");
            report = report.replace(js(/(<td)>(#[^#].+?<\/td><\/tr>)/gm), "$1 BGCOLOR=\"" + colour2 + "\">$2");
        }
        if (markSign == "вида [1]") {
            report = report.replace(js(/(<td align=\"right\")>(.*?\[1\]<\/td>)/gm), "$1 BGCOLOR=\"" + colour2 + "\">$2");
            report = report.replace(js(/(<td)>(\[1\].+?<\/td><\/tr>)/gm), "$1 BGCOLOR=\"" + colour2 + "\">$2");
        }
        if (markSign == "вида {1}") {
            report = report.replace(js(/(<td align=\"right\")>(.*?\{1\}<\/td>)/gm), "$1 BGCOLOR=\"" + colour2 + "\">$2");
            report = report.replace(js(/(<td)>(\{1\}.+?<\/td><\/tr>)/gm), "$1 BGCOLOR=\"" + colour2 + "\">$2");
        }
        if (markSign == "вида [~1~]") {
            report = report.replace(js(/(<td align=\"right\")>(.*?\[~1~\]<\/td>)/gm), "$1 BGCOLOR=\"" + colour2 + "\">$2");
            report = report.replace(js(/(<td)>(\[~1~\].+?<\/td><\/tr>)/gm), "$1 BGCOLOR=\"" + colour2 + "\">$2");
        }
        if (markSign == "вида {~1~}") {
            report = report.replace(js(/(<td align=\"right\")>(.*?\{~1~\}<\/td>)/gm), "$1 BGCOLOR=\"" + colour2 + "\">$2");
            report = report.replace(js(/(<td)>(\{~1~\}.+?<\/td><\/tr>)/gm), "$1 BGCOLOR=\"" + colour2 + "\">$2");
        }

        // закрасить пустые ячейки:
        report = report.replace(js(/<td><\/td>/mg), "<td BGCOLOR=\"" + colour0d + "\"><\/td>");
        report = report.replace(js(/<td align="right"><\/td>/mg), "<td BGCOLOR=\"" + colour0d + "\"><\/td>");

        // закрасить средний столбец с номерами будущих сносок:
        report = report.replace(js(/(<\/td><td align="center")(>\d+<\/td>)/g), "$1 BGCOLOR=\"" + colour0e + "\"$2");

        // оформляем цветным текстом номер будущей сноски в среднем столбце, ранее помеченный (000) находящийся в строке с разными числовыми значениями маркеров знака и текста сноски:
        report = report.replace(js(new RegExp("(BGCOLOR=\\\"" + colour0e + "\\\">)000(\\d+)(?=</td><td)", "g")), "$1<FONT color=\"" + colorErr + "\">$2</FONT>");


        var reportDo = tx("<h2 align=\"center\">Таблица соответствия маркеров будущих сносок</h2><table  width=\"100%\" border=\"1\" cellpadding=\"5\" cellspacing=\"5\"><tr BGCOLOR=\"", "<h2 align=\"center\">Table matching the markers of future footnotes</h2><table  width=\"100%\" border=\"1\" cellpadding=\"5\" cellspacing=\"5\"><tr BGCOLOR=\"") + colour0a + tx("\"><th height=\"40\">Сноска (", "\"><th height=\"40\">Footnote (") + z + tx(")</th><th>№</th><th>Текст сноски (", ")</th><th>No.</th><th>Footnote text (") + t + ")</th></tr>";

        var reportPosle = tx("</table><p align=\"center\">Скрипт \"", "</table><p align=\"center\">Script \"") + name + "\" v." + version + " (" + avtor + ")</p>";
        report = reportDo + "" + report + "" + reportPosle;

       /*  MsgBox(report);
        window.clipboardData.setData("text",report); // данные в буфер обмена для Excel и т. п. программ. */

    // для показа в IE:
    if (display == 0) {
        await MyMsgWindow(report);
    }
    // для показа в браузере по умолчанию:
    if (display == 1) {
        await WriteFile();
    }

    }

    async function MyMsgWindow(report) {
        await host.report(report);
    }

    async function WriteFile() {
        await host.writeFile(filePatch, report);
    }
        // ================================
}
